let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=status_heartbeat,status=started value=1 ' + nowNs;
return msg;

function clean(v) { return (v && v !== 'unknown' && v !== 'unavailable') ? v : null; }
const now = new Date().toISOString();
const reports = [];

// This flow's own successful execution IS the 'HA is up' signal — see
// this tab's info note for why /api/config enrichment isn't implemented.
reports.push({
    category: 'ha', component: 'ha_core',
    last_run_at: now, last_status: 'success',
    expected_frequency_minutes: 15,
    detail: 'Signal is this heartbeat itself running — real HA version/uptime not implemented yet, see flow tab info.'
});

function pushComponent(component, prefix, expectedMin) {
    const ok = msg[prefix + '_last_attempt_ok'];
    reports.push({
        category: 'nodered',
        component: component,
        last_run_at: clean(msg[prefix + '_last_attempt']),
        last_status: ok === 'on' ? 'success' : (ok === 'off' ? 'failed' : 'unknown'),
        last_error: clean(msg[prefix + '_last_error']),
        expected_frequency_minutes: expectedMin,
    });
}
pushComponent('oura_sync', 'oura', 240);
pushComponent('godaddy_pull', 'godaddy', 15);
pushComponent('bodycomp_import', 'bodycomp', 1440);
// Fulgrim validation pass (Aug 2026) — the 3 flows added that session
// (PLAN.md §19/20). medical_history_import and wherewhen_restore are
// manual/on-demand only (no real cadence), so expectedMin is null —
// overdue_info() in db.php already treats a null expected_frequency_minutes
// as "not schedule-based, nothing to compute" rather than always-overdue.
// wherewhen_export has a real weekly schedule (Sunday 3am) alongside its
// manual trigger, so it gets a real expectedMin (7 days).
pushComponent('medical_history_import', 'mhi', null);
pushComponent('wherewhen_export', 'wde', 10080);
pushComponent('wherewhen_restore', 'wdr', null);
// analysis_engine (Fulgrim Flux-engine pass, Aug 2026) — daily is its
// tightest scheduled tier (weekly/monthly also run but daily is what
// 'overdue' should track against; all-data is manual-only like the two
// manual flows above and isn't reflected in this single expectedMin).
pushComponent('analysis_engine', 'ae', 1440);

msg.reports = reports;
return msg;

msg.url = msg.secrets.godaddy_base_url + '/api/status_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ reports: msg.reports });
return msg;

const resp = msg.payload;
if (!resp || resp.success !== true) {
    msg.job_failed = true;
    msg.failure_code = resp && resp.error === 'auth_invalid' ? 'godaddy_auth_failed' : 'godaddy_error_response';
    msg.failure_detail = JSON.stringify(resp).slice(0, 300);
}

function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }
const nowNs = Date.now() * 1000000;
const lines = (msg.reports || []).map(r => {
    const ok = r.last_status === 'success' ? 1 : 0;
    return 'system_status_snapshot,category=' + esc(r.category) + ',component=' + esc(r.component) + ' status_ok=' + ok + ' ' + nowNs;
});
msg.influx_snapshot_lines = lines;
return msg;

if (!msg.influx_snapshot_lines.length) {
    return [null, msg];
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_snapshot_lines.join('\n');
return [msg, msg];

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
if (msg.job_failed) {
    const code = msg.failure_code || 'unknown_error';
    const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
    msg.influx_finish_point = 'sync_job_runs,job_name=status_heartbeat,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
    node.warn('Status Heartbeat failed: ' + code + ' - ' + msg.failure_detail);
} else {
    msg.influx_finish_point = 'sync_job_runs,job_name=status_heartbeat,status=success report_count=' + (msg.reports ? msg.reports.length : 0) + ',duration_ms=' + durationMs + ' ' + nowNs;
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;
